sys_script_include.script:
var MedicationUtils = Class.create();
MedicationUtils.prototype = {
    initialize: function() {
		this.source = new GlideRecord('u_medication');
    },

	calculateTotalDosage : function(medId){
		freqMap = {
			'once_daily' : 1,
			'twice_daily' : 2,
			'thrice_daily': 3
		};
		this.source.get(medId);
		var total_dosage = parseInt(this.source.u_dosage) * freqMap[this.source.getValue('u_frequency')];
		return total_dosage;
	},

	checkAvailability : function(medId){
		this.source.get(medId);
		if(this.source.u_available){
			return true;
		}
		else{
			return false;
		}
	},

	fetchMedicationDetailsById : function(medId){
		this.source.get(medId);
		var results = {
			med_num : this.source.getValue('number'),
			med_pat_id : this.source.getValue('u_patient_id'),
			med_name : this.source.getValue('u_medication_name'),
			med_dose : this.source.getValue('u_dosage'),
			med_freq : this.source.getValue('u_frequency'),
			med_stat : this.source.getValue('u_status'),
			med_total_dose : this.source.getValue('u_total_dosage'),
			med_start_date : this.source.getValue('u_start_date'),
			med_end_date : this.source.getValue('u_end_date'),
			med_doc : this.source.getValue('u_prescribing_doctor')
		};
		return results;
	},

	fetchMedicationDetailsByPatientId(patId){
		this.source.addQuery('u_patient_id', patId);
		this.source.query();
		return this.source;
	},


    type: 'MedicationUtils'
};
